import{_ as o,o as t,c as l,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2017-MAY-04 :: Ceph Performance Weekly","description":"","frontmatter":{"title":"2017-MAY-04 :: Ceph Performance Weekly","date":"2017-05-17T00:00:00.000Z","updated":"2017-05-17T00:00:00.000Z","tags":["Ceph性能优化","分布式存储","RocksDB","BlueStore","数据恢复"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.md","filePath":"posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.md","lastUpdated":1780459816000}'),s={name:"posts/2017/2017-MAY-04_-_-_Ceph_Performance_Weekly.md"};function n(i,e,a,g,p,_){return t(),l("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月X日</p><p><strong>参会人员</strong>： Chris, Mark, James (Alibaba), Josh, Sage, Andy (kestrels), Stu, Ali (Alibaba), Johnson (Alibaba)</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. Ceph性能优化</strong></p><ul><li><strong>RocksDB读前加速</strong>： Mark介绍通过启用RocksDB读前加速功能，在压缩过程中提高性能的方法，将读取时间从95%降低到18%，等待时间从82%降低到18%。</li><li><strong>编码/解码框架迁移</strong>： Sage提交PR移除旧编码/解码代码并迁移到新框架，提高性能和可维护性。</li><li><strong>BlueStore优化</strong>： Sage提交PR将BlueStore放置在共享设备中间，讨论了数据放置位置对性能的影响。</li><li><strong>锁优化</strong>： 讨论了锁优化，包括消除重复块位置和锁冲突。</li><li><strong>CRC缓存</strong>： Andy (kestrels) 提交PR改进CRC缓存，提高性能。</li><li><strong>自适应限流</strong>： 讨论自适应限流机制优化性能和降低延迟。</li><li><strong>OST性能优化</strong>： Johnson (Alibaba) 提出优化OST性能的方案。</li><li><strong>游戏时钟</strong>： 讨论游戏时钟的实现和性能。</li></ul><p><strong>2. Ceph恢复</strong></p><ul><li><strong>阿里巴巴团队</strong>： 分享恢复优化工作，包括同步恢复和部分恢复，讨论性能提升和优化方向。</li><li><strong>异步恢复</strong>： Josh分享异步恢复工作，讨论与阿里巴巴团队的协作。</li></ul><p><strong>3. 其他</strong></p><ul><li><strong>OST性能优化</strong>： Johnson (Alibaba) 提出优化OST性能的方案。</li><li><strong>游戏时钟</strong>： 讨论游戏时钟的实现和性能。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Mark将继续优化RocksDB读前加速功能。</li><li>Sage将继续改进BlueStore和CRC缓存。</li><li>Andy (kestrels) 将完善CRC缓存PR。</li><li>Josh将优化异步恢复机制。</li><li>Johnson (Alibaba) 将继续优化OST性能。</li><li>阿里巴巴团队将继续优化Ceph恢复功能。</li></ul><p><strong>下次会议</strong>：</p><ul><li>时间：2023年11月X日</li><li>内容：Ceph分布式存储项目进展及讨论</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了一些计算机科学/ceph相关领域英文原文的关键词，如RocksDB, BlueStore, CRC, PG, OST, RBD等。</li><li>会议纪要仅供参考，具体细节可能需要查阅相关PR和邮件。</li></ul>',17)])])}const u=o(s,[["render",n]]);export{h as __pageData,u as default};
